def check_square_divisors(g):
    # Finds all divisors d^2 of g, where d >= 2
    non_trivial_squares = []
    for d in range(2, int(g**0.5) + 1):
        d_sq = d * d
        if g % d_sq == 0:
            non_trivial_squares.append(d_sq)
    return len(non_trivial_squares) >= 2

